import { useEffect, useState } from 'react';
import axios from '../api/axios';
import {
  FaUser,
  FaEnvelope,
  FaUserShield,
  FaExclamationTriangle,
} from 'react-icons/fa';

function Profile() {
  const [user, setUser] = useState(null);
  const [message, setMessage] = useState('');

  useEffect(() => {
    const fetchProfile = async () => {
      const token = localStorage.getItem('token');

      if (!token) {
        setMessage('🔒 You are not logged in.');
        return;
      }

      try {
        const res = await axios.get('/profile', {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });

        setUser(res.data);
      } catch (err) {
        console.error('Profile fetch error:', err);
        setMessage('⚠ Failed to fetch profile. Please log in again.');
        localStorage.removeItem('token');
      }
    };

    fetchProfile();
  }, []);

  return (
    <div
      className="d-flex justify-content-center align-items-center"
      style={{ minHeight: '100vh', backgroundColor: '#f8f9fa' }}
    >
      <div
        className="w-100 bg-white shadow rounded p-4 d-flex flex-column align-items-center"
        style={{ maxWidth: '400px', minHeight: '550px' }}
      >
        <div className="text-center mb-4">
          <div
            className="rounded-circle bg-primary text-white d-flex align-items-center justify-content-center"
            style={{ width: '100px', height: '100px', fontSize: '40px', margin: '0 auto' }}
          >
            <FaUser />
          </div>
          <h4 className="mt-3">Your Profile</h4>
        </div>

        {message && (
          <div className="alert alert-warning d-flex align-items-center w-100">
            <FaExclamationTriangle className="me-2" />
            {message}
          </div>
        )}

        {user ? (
          <div className="text-center w-100">
            <p>
              <FaUser className="me-2 text-primary" />
              <strong>Name:</strong> {user.name}
            </p>
            <p>
              <FaEnvelope className="me-2 text-secondary" />
              <strong>Email:</strong> {user.email}
            </p>
            <p>
              <FaUserShield className="me-2 text-success" />
              <strong>Role:</strong> {user.role}
            </p>
          </div>
        ) : (
          !message && <p className="text-center">⏳ Loading your profile...</p>
        )}
      </div>
    </div>
  );
}

export default Profile;
